INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is ''cationic dye'' primarily used to color, given its positively charged dye molecules?', '["Acrylic fiber, which carries negatively charged (anionic) sites that attract and bond with cationic dye molecules","Only 100% cotton fabric, with no relevance to any synthetic fiber","Only wool fiber, identical in mechanism to acid dye","Polyester fiber exclusively, using the same mechanism as disperse dye"]'::jsonb, 'Acrylic fiber, which carries negatively charged (anionic) sites that attract and bond with cationic dye molecules', 'Cationic (basic) dyes carry a positive charge and are specifically suited to acrylic fiber, which contains anionic (negatively charged) dye sites built into its polymer structure — giving cationic dyes strong affinity and often very bright, vivid shades on acrylic.', 2, '{"cationic-dye"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why do cationic dyes generally NOT work well on untreated cotton or polyester fiber?', '["Cotton and standard polyester lack the anionic dye-receptive sites that acrylic fiber has, so cationic dye has little chemical affinity for them","Cationic dyes work equally well on every fiber type with no exceptions","Cotton and polyester actively repel all dye classes, including cationic dye, identically","Cationic dyes are chemically identical to reactive dyes and behave the same on cotton"]'::jsonb, 'Cotton and standard polyester lack the anionic dye-receptive sites that acrylic fiber has, so cationic dye has little chemical affinity for them', 'Cationic dye''s affinity mechanism specifically relies on anionic sites (like those in acrylic''s polymer structure); standard cotton and polyester don''t have this same site structure, so cationic dyes lack a strong bonding mechanism and generally aren''t the appropriate dye class for them.', 2, '{"cationic-dye-limitations"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is a ''union dyeing'' recipe designed to address, when dyeing a blended fabric (e.g., polyester/cotton)?', '["Achieving a matching, coordinated shade across BOTH fiber types in the blend, since each fiber type may need a different dye class to take up color","Dyeing only one of the two fiber types while deliberately leaving the other completely undyed and white","A method that only works on 100% single-fiber-type fabric, never on blends","A recipe that uses zero dye chemicals, relying only on mechanical color transfer"]'::jsonb, 'Achieving a matching, coordinated shade across BOTH fiber types in the blend, since each fiber type may need a different dye class to take up color', 'Since polyester and cotton (for example) each require different dye classes (disperse for polyester, reactive/direct for cotton) to take up color effectively, a union dyeing recipe combines both dye classes in a coordinated process to achieve a matching, unified shade across the whole blended fabric.', 2, '{"union-dyeing"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is a ''cross-dyeing'' effect, sometimes used deliberately for design purposes on blended fabrics?', '["Using a SINGLE dye class that colors one fiber type in the blend but leaves the other fiber type undyed (or a different resulting shade), creating a heather/melange or two-tone effect","A dyeing method that must always dye every fiber type in a blend to the exact identical shade","A synonym for garment dyeing with no relation to fiber blends specifically","A method used only to dye 100% single-fiber fabric, never blends"]'::jsonb, 'Using a SINGLE dye class that colors one fiber type in the blend but leaves the other fiber type undyed (or a different resulting shade), creating a heather/melange or two-tone effect', 'Cross-dyeing deliberately exploits dye-class selectivity: applying a dye that only takes up on one fiber component of a blend (leaving the other fiber undyed or differently colored) to create heather/melange effects or intentional tonal contrast — the opposite goal from union dyeing''s uniform match.', 2, '{"cross-dyeing"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What does ''dye bath exhaustion curve'' (exhaustion over time/temperature) typically look like, and why is monitoring it useful?', '["It typically shows increasing dye uptake over time/temperature toward a plateau; monitoring it helps confirm the dyeing is proceeding as expected and predict when the process is complete","It shows dye exhaustion decreasing steadily to zero throughout the entire process, with no plateau","Exhaustion curves are identical for every dye class and process, so monitoring provides no useful information","The exhaustion curve only matters for the fixation stage, not the dyeing stage itself"]'::jsonb, 'It typically shows increasing dye uptake over time/temperature toward a plateau; monitoring it helps confirm the dyeing is proceeding as expected and predict when the process is complete', 'As a dyeing process proceeds, dye typically exhausts progressively from the bath onto the substrate, often following a characteristic time/temperature curve that levels off (plateaus) as equilibrium is approached; monitoring this curve (directly or via bath color/absorbance) helps confirm normal process behavior and predict process completion or detect problems.', 2, '{"exhaustion-curve"}'::text[]);
